kingoftokyodueltokyobay.css:
html[data-theme=dark].bgaext_bright .bga-cards_card,
html[data-theme=dark].bgaext_bright .monster-board,
html[data-theme=dark].bgaext_bright .life-wheel .inner,
html[data-theme=dark].bgaext_bright .life-wheel .outer,
html[data-theme=dark].bgaext_bright .bga-cards_card > .bga-cards_card-sides > .bga-cards_card-side,
html[data-theme=dark].bgaext_bright #table #table-center #board-wrapper {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_bright .card-stock .card.bga-cards_disabled-card {
  filter: var(--ext-bright) contrast(0.6);
}
html[data-theme=dark].bgaext_bright .banned-monster {
  filter: var(--ext-bright) grayscale(1);
}
html[data-theme=dark].bgaext_dark {
  --ext-overlay-color: #0003;
}
html[data-theme=dark].bgaext_dark #bga-zoom_controls {
  --bga-zoom-button-color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .bgaext_overlay {
  background-color: #c7cbd1 !important;
}
html[data-theme=dark].bgaext_dark .difficulty-wrapper .difficulty {
  background: #000;
}
html[data-theme=dark].bgaext_dark #stickers .sticker {
  background: var(--dark-20);
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .icon.skull {
  filter: invert();
}
html[data-theme=dark].bgaext_dark #stickers .sticker .sticker-name {
  background: #971c41;
}
html[data-theme=dark].bgaext_dark #stickers .sticker:not(.done) .sticker-name {
  background: #664d55;
}

moustache.css:
html[data-theme=dark].bgaext_bright .mf_item,
html[data-theme=dark].bgaext_bright .mf_log_card > div {
  filter: var(--ext-bright);
}
html[data-theme="dark"].bgaext_dark.darkpanel #player_boards .player-board.mf_zone_team_1 {
  background-color: #2f040f !important;
}
html[data-theme="dark"].bgaext_dark.darkpanel #player_boards .player-board.mf_zone_team_2 {
  background-color: #0b1928 !important;
}
html[data-theme=dark].bgaext_dark body {
  background: #fff;
}
html[data-theme=dark].bgaext_dark body:before {
  filter: invert() hue-rotate(180deg);
  opacity: 0.9;
}
html[data-theme=dark].bgaext_dark .mf_zone_team_1 {
  background-color: #2f040f;
}
html[data-theme=dark].bgaext_dark .mf_zone_team_2 {
  background-color: #0b1928;
}
html[data-theme=dark].bgaext_dark .mf_help {
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .mf_zone_result_title {
  background-color: var(--dark-back);
}

risktheabyss.css:
html[data-theme=dark].bgaext_dark {
  --ext-overall-color: #0008;
}
html[data-theme=dark].bgaext_dark #overall-content {
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark #rta_tray,
html[data-theme=dark].bgaext_dark .rta_tray_reroll {
  border-color: var(--light-50);
}
html[data-theme=dark].bgaext_dark .rta_tray_keep .rta_tray_badge {
  background-color: #62d0bed9;
}
html[data-theme=dark].bgaext_dark .rta_tray_reroll .rta_tray_badge {
  background-color: #965c3cd9;
}
html[data-theme=dark].bgaext_dark .rta_tray_reroll .rta_tray_dice {
  background: #e7a14b12;
  background-image: repeating-linear-gradient(-45deg, #e7a14b24 0 4px, #e7a14b00 4px 9px);
  border-color: #e7a14b80;
}
html[data-theme=dark].bgaext_dark .rta_player {
  background: var(--dark-back);
}
html[data-theme=dark].bgaext_dark .rta_player_name {
  text-shadow: none;
}
html[data-theme=dark].bgaext_dark #rta_aid_dialog {
  background: var(--dark-20);
}
html[data-theme=dark].bgaext_dark #rta_aid_title {
  color: var(--light-60);
}

zenso.css:
html[data-theme=dark].bgaext_bright .mf_item_back,
html[data-theme=dark].bgaext_bright .mf_item_front,
html[data-theme=dark].bgaext_bright .mf_log_card > div,
html[data-theme=dark].bgaext_bright .mf_panel_icon > div {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_dark body:before {
  filter: invert() hue-rotate(180deg);
}
html[data-theme=dark].bgaext_dark .mf_label > div {
  background-color: var(--dark-10);
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .mf_scoring_container {
  background-color: var(--dark-back);
}
html[data-theme=dark].bgaext_dark .mf_scoring_header {
  border-color: #785457;
}
html[data-theme=dark].bgaext_dark .mf_scoring {
  color: #ab878a;
}
html[data-theme=dark].bgaext_dark .mf_scoring_header_hand {
  color: var(--light-60);
}
